insert into public.army_rosters (id, name, source_file, catalogue_name, game_system_name) values ('wraith-kern-basis', 'Wraith Kern - Basis', 'armies/Wraith Kern - Basis.json', '', 'Warhammer 40,000 10th Edition') on conflict (id) do update set name = excluded.name, source_file = excluded.source_file, catalogue_name = excluded.catalogue_name, game_system_name = excluded.game_system_name, updated_at = now();
insert into public.army_units (id, roster_id, source_file, name, model_count, profile_name, movement_text, toughness, save, wounds_per_model, leadership_text, objective_control, raw_selection) values ('guidos-army-aggro-style::66086000000000', 'guidos-army-aggro-style', 'Guidos Army - aggro style.json', 'Blade Champion', 1, 'Blade Champion', '6"', 6, 2, 6, '6+', 2, '{"rules":[{"description":"During the Declare Battle Formations step, if every model in a unit has this ability, you can set it up in Reserves instead of setting it up on the battlefield. If you do, in the Reinforcements step of one of your Movement phases you can set up this unit anywhere on the battlefield that is more than 9\" horizontally away from all enemy models.\n\nIf a unit with the Deep Strike ability arrives from Strategic Reserves, the controlling player can choose for that unit to be set up either using the rules for Strategic Reserves or using the Deep Strike ability.","id":"7cb5-dd6b-dd87-ad3b","name":"Schocktruppen","hidden":false,"page":39},{"description":"While a Bodyguard unit contains a Leader, it is known as an Attached unit and, with the exception of rules that are triggered when units are destroyed (pg 12), it is treated as a single unit for all rules purposes. Each time an attack targets an Attached unit, until the attacking unit has resolved all of its attacks, you must use the Toughness characteristic of the Bodyguard models in that unit, even if a Leader in that unit has a different Toughness characteristic. Each time an attack successfully wounds an Attached unit, that attack cannot be allocated to a Character model in that unit, even if that Character model has lost one or more wounds or has already had attacks allocated to it this phase. As soon as the last Bodyguard model in an Attached unit has been destroyed, any attacks made against that unit that have yet to be allocated can then be allocated to Character models in that unit.\n\nEach time the last model in a Bodyguard unit is destroyed, each CHARACTER unit that is part of that Attached unit becomes a separate unit, with its original Starting Strength. If this happens as the result of an attack, they become separate units after the attacking unit has resolved all of its attacks. \n\nEach time the last model in a CHARACTER unit that is attached to a Bodyguard unit is destroyed and there is not another CHARACTER unit attached, that Attached unit’s Bodyguard unit becomes a separate unit, with its original Starting Strength. If this happens as the result of an attack, they become separate units after the attacking unit has resolved all of its attacks. \n\nEach time a unit that is part of an Attached unit is destroyed, it does not have the keywords of any other units that make up that Attached unit (unless it has those keywords on its own datasheet) for the purposes of any rules that would be triggered when that unit is destroyed.","id":"b4dd-3e1f-41cb-218f","name":"Anführer","hidden":false,"page":39},{"description":"Each time a unit with this ability is selected to fight, select one of the Ka''tah stances below. Until that unit has finished making its attacks, the selected Stance is active for it and it gains the relevant ability.\n\n■ DACATARAI STANCE\nMelee weapons equipped by models in this unit have the [SUSTAINED HITS 1] ability.\n■ RENDAX STANCE\nMelee weapons equipped by models in this unit have the [LETHAL HITS] ability.","id":"e348-7090-3aff-ee2c","name":"Martial Ka''tah","hidden":false}],"profiles":[{"characteristics":[{"$text":"This model can be attached to the following units:\n■ Custodian Guard\n■ Custodian Wardens","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"1a70-8702-4179-b711","name":"Anführer","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"6\"","name":"B","typeId":"e703-ecb6-5ce7-aec1"},{"$text":"6","name":"W","typeId":"d29d-cf75-fc2d-34a4"},{"$text":"2+","name":"RW","typeId":"450-a17e-9d5e-29da"},{"$text":"6","name":"LP","typeId":"750a-a2ec-90d3-21fe"},{"$text":"6+","name":"MW","typeId":"58d2-b879-49c7-43bc"},{"$text":"2","name":"MK","typeId":"bef7-942a-1a23-59f8"}],"id":"11f7-2788-9bfd-177b","name":"Blade Champion","hidden":false,"typeId":"c547-1836-d8a-ff4f","typeName":"Einheit","from":"entry"},{"characteristics":[{"$text":"Once per battle, in your Charge phase, this model''s unit is eligible to declare a charge in a turn in which it Advanced.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"be52-2414-896d-55fc","name":"Martial Inspiration","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"While this model is leading a unit, you can re-roll Charge rolls made for that unit.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"31ef-fcd4-c165-a95d","name":"Swift Onslaught","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"Dieses Modell hat einen Unverwundbarkeitswurf von 4+.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"4042-b2c1-d581-dbe7","name":"Invulnerable Save","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"}],"selections":[{"categories":[{"id":"5c0e-4c31-d51b-e470","name":"Kriegsherr","entryId":"5c0e-4c31-d51b-e470","primary":false}],"id":"rjw3gzo","name":"Kriegsherr","entryId":"473-b72d-a70b-e3aa::a233-1cf6-8bf2-aeb8::0574-f558-2957-584f","number":1,"type":"upgrade","from":"entry"},{"profiles":[{"characteristics":[{"$text":"**^^Adeptus Custodes Infantry^^** model only. The first time the bearer is destroyed, roll one D6 at the end of the phase. On a 2+, set the bearer back up on the battlefield, as close as possible to where it was destroyed and not within Engagement Range of one or more enemy units, with its full wounds remaining.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"e771-0d0c-4e40-e8ff","name":"Superior Creation","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"}],"costs":[{"name":"pkt","typeId":"51b2-306e-1021-d207","value":25}],"id":"1hk0kpr","name":"Superior Creation","entryId":"473-b72d-a70b-e3aa::13c5-668b-33bd-328f::2ede-aacf-f98d-83d5","entryGroupId":"473-b72d-a70b-e3aa::13c5-668b-33bd-328f::a43b-fe98-3d93-435d","number":1,"type":"upgrade","from":"group","group":"Enhancements"},{"rules":[{"description":"Weapons with **[PRECISION]** in their profile are known as Precision weapons. Each time an attack made with such a weapon successfully wounds an Attached unit, if a Character model in that unit is visible to the attacking model, the attacking model’s player can choose to have that attack allocated to that Character model instead of following the normal attack sequence.","id":"9143-31ae-e0a6-6007","name":"Präzision","hidden":false,"page":26},{"description":"Weapons with **[SUSTAINED HITS X]** in their profile are known as Sustained Hits weapons. Each time an attack is made with such a weapon, if a Critical Hit is rolled, that attack scores a number of additional hits on the target as denoted by ‘x’","id":"1897-c22c-9597-12b1","name":"Trefferhagel","hidden":false,"page":28},{"description":"Weapons with **[DEVASTATING WOUNDS]** in their profile are known as Devastating Wounds weapons. Each time an attack is made with such a weapon, if that attack scores a Critical Wound, no saving throw of any kind can be made against that attack (including invulnerable saving throws). Such attacks are only allocated to models after all other attacks made by the attacking unit have been allocated and resolved. After that attack is allocated and after any modifiers are applied, it inflicts a number of mortal wounds on the target equal to the Damage characteristic of that attack, instead of inflicting damage normally.","id":"be1e-ac8e-1e2c-3528","name":"Verheerende Verwundung","hidden":false,"page":28}],"profiles":[{"characteristics":[{"$text":"Nahkampf","name":"Reichweite","typeId":"914c-b413-91e3-a132"},{"$text":"6","name":"A","typeId":"2337-daa1-6682-b110"},{"$text":"2+","name":"KG","typeId":"95d1-95f-45b4-11d6"},{"$text":"7","name":"S","typeId":"ab33-d393-96ce-ccba"},{"$text":"-2","name":"DS","typeId":"41a0-1301-112a-e2f2"},{"$text":"2","name":"SW","typeId":"3254-9fe6-d824-513e"},{"$text":"Präzision","name":"Schlüsselwort","typeId":"893f-9000-ccf7-648e"}],"id":"7953-e1ea-8b27-b564","name":"➤ Vaultswords - Behemor","hidden":false,"typeId":"8a40-4aaa-c780-9046","typeName":"Nahkampfwaffen","from":"entry"},{"characteristics":[{"$text":"Nahkampf","name":"Reichweite","typeId":"914c-b413-91e3-a132"},{"$text":"9","name":"A","typeId":"2337-daa1-6682-b110"},{"$text":"2+","name":"KG","typeId":"95d1-95f-45b4-11d6"},{"$text":"5","name":"S","typeId":"ab33-d393-96ce-ccba"},{"$text":"-1","name":"DS","typeId":"41a0-1301-112a-e2f2"},{"$text":"1","name":"SW","typeId":"3254-9fe6-d824-513e"},{"$text":"Trefferhagel 1","name":"Schlüsselwort","typeId":"893f-9000-ccf7-648e"}],"id":"d09f-3496-dc55-e6b4","name":"➤ Vaultswords - Hurricanis","hidden":false,"typeId":"8a40-4aaa-c780-9046","typeName":"Nahkampfwaffen","from":"entry"},{"characteristics":[{"$text":"Nahkampf","name":"Reichweite","typeId":"914c-b413-91e3-a132"},{"$text":"5","name":"A","typeId":"2337-daa1-6682-b110"},{"$text":"2+","name":"KG","typeId":"95d1-95f-45b4-11d6"},{"$text":"6","name":"S","typeId":"ab33-d393-96ce-ccba"},{"$text":"-3","name":"DS","typeId":"41a0-1301-112a-e2f2"},{"$text":"3","name":"SW","typeId":"3254-9fe6-d824-513e"},{"$text":"Verheerende Verwundung","name":"Schlüsselwort","typeId":"893f-9000-ccf7-648e"}],"id":"7ffc-b8d9-10a7-7e4e","name":"➤ Vaultswords - Victus","hidden":false,"typeId":"8a40-4aaa-c780-9046","typeName":"Nahkampfwaffen","from":"entry"}],"categories":[{"id":"ccdd-3987-11ed-90cd","name":"Nahkampfwaffe","entryId":"ccdd-3987-11ed-90cd","primary":false}],"id":"68agf8l","name":"Vaultswords","entryId":"473-b72d-a70b-e3aa::f906-23b-58ce-a3df","entryGroupId":"473-b72d-a70b-e3aa::f610-42a4-d114-3181","number":1,"type":"upgrade","from":"group","group":"Ausrüstung"}],"costs":[{"name":"pkt","typeId":"51b2-306e-1021-d207","value":120}],"categories":[{"id":"691e-fed6-a4b4-c66","name":"Blade Champion","entryId":"691e-fed6-a4b4-c66","primary":false},{"id":"cf47-a0d7-7207-29dc","name":"Infanterie","entryId":"cf47-a0d7-7207-29dc","primary":false},{"id":"9cfd-1c32-585f-7d5c","entryId":"9cfd-1c32-585f-7d5c","name":"Charatker","primary":true},{"id":"aff3-d6a3-2a95-9dc","name":"Imperium","entryId":"aff3-d6a3-2a95-9dc","primary":false},{"id":"eea5-aeaf-bbf0-d5ee","name":"Fraktion; Adeptus Custodes","entryId":"eea5-aeaf-bbf0-d5ee","primary":false}],"id":66086000000000,"name":"Blade Champion","entryId":"473-b72d-a70b-e3aa::48b7-e713-d5b1-f11c","number":1,"type":"model","from":"entry"}'::jsonb) on conflict (id) do update set name = excluded.name, model_count = excluded.model_count, profile_name = excluded.profile_name, movement_text = excluded.movement_text, toughness = excluded.toughness, save = excluded.save, wounds_per_model = excluded.wounds_per_model, leadership_text = excluded.leadership_text, objective_control = excluded.objective_control, raw_selection = excluded.raw_selection, updated_at = now();
