insert into public.army_units (id, roster_id, source_file, name, model_count, profile_name, movement_text, toughness, save, wounds_per_model, leadership_text, objective_control, raw_selection) values ('guidos-army-aggro-style::xs9zrnr', 'guidos-army-aggro-style', 'Guidos Army - aggro style.json', 'Custodian Guard', 4, 'Custodian Guard', '6"', 6, 2, 3, '6+', 2, '{"rules":[{"description":"During the Declare Battle Formations step, if every model in a unit has this ability, you can set it up in Reserves instead of setting it up on the battlefield. If you do, in the Reinforcements step of one of your Movement phases you can set up this unit anywhere on the battlefield that is more than 9\" horizontally away from all enemy models.\n\nIf a unit with the Deep Strike ability arrives from Strategic Reserves, the controlling player can choose for that unit to be set up either using the rules for Strategic Reserves or using the Deep Strike ability.","id":"7cb5-dd6b-dd87-ad3b","name":"Schocktruppen","hidden":false,"page":39},{"description":"Each time a unit with this ability is selected to fight, select one of the Ka''tah stances below. Until that unit has finished making its attacks, the selected Stance is active for it and it gains the relevant ability.\n\n■ DACATARAI STANCE\nMelee weapons equipped by models in this unit have the [SUSTAINED HITS 1] ability.\n■ RENDAX STANCE\nMelee weapons equipped by models in this unit have the [LETHAL HITS] ability.","id":"e348-7090-3aff-ee2c","name":"Martial Ka''tah","hidden":false}],"profiles":[{"characteristics":[{"$text":"Each time a model in this unit makes an attack, re-roll a Wound roll of 1. While this unit is within range of an objective marker you control, you can re-roll the Wound roll instead.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"07c7-730f-5219-ef8f","name":"Stand Vigil","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"Once per battle, in your Shooting phase, after the unit has shot, it can shoot again.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"9c46-e189-463c-266e","name":"Sentinel Storm","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"Models in this unit have a 4+ invulnerable save.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"0300-84b9-69cf-b64f","name":"Invulnerable Save","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"}],"selections":[{"profiles":[{"characteristics":[{"$text":"6\"","name":"B","typeId":"e703-ecb6-5ce7-aec1"},{"$text":"6","name":"W","typeId":"d29d-cf75-fc2d-34a4"},{"$text":"2+","name":"RW","typeId":"450-a17e-9d5e-29da"},{"$text":"3","name":"LP","typeId":"750a-a2ec-90d3-21fe"},{"$text":"6+","name":"MW","typeId":"58d2-b879-49c7-43bc"},{"$text":"2","name":"MK","typeId":"bef7-942a-1a23-59f8"}],"id":"ffb0-e197-3a20-7515","name":"Custodian Guard","hidden":false,"typeId":"c547-1836-d8a-ff4f","typeName":"Einheit","from":"entry"}],"selections":[{"rules":[{"description":"Weapons with **[ASSAULT]** in their profile are known as Assault weapons. If a unit that Advanced this turn contains any models equipped with Assault weapons, it is still eligible to shoot in this turn’s Shooting phase. When such a unit is selected to shoot, you can only resolve attacks using Assault weapons its models are equipped with.","id":"fc8a-8c24-bae9-cc1c","name":"Strum","hidden":false,"page":25}],"profiles":[{"characteristics":[{"$text":"Nahkampf","name":"Reichweite","typeId":"914c-b413-91e3-a132"},{"$text":"5","name":"A","typeId":"2337-daa1-6682-b110"},{"$text":"2+","name":"KG","typeId":"95d1-95f-45b4-11d6"},{"$text":"7","name":"S","typeId":"ab33-d393-96ce-ccba"},{"$text":"-2","name":"DS","typeId":"41a0-1301-112a-e2f2"},{"$text":"2","name":"SW","typeId":"3254-9fe6-d824-513e"},{"$text":"-","name":"Schlüsselwort","typeId":"893f-9000-ccf7-648e"}],"id":"3665-5bcf-a899-fad","name":"Guardian Spear","hidden":false,"typeId":"8a40-4aaa-c780-9046","typeName":"Nahkampfwaffen","from":"entry"},{"characteristics":[{"$text":"24\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"2","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"2+","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"4","name":"S","typeId":"2229-f494-25db-c5d3"},{"$text":"-1","name":"DS","typeId":"9ead-8a10-520-de15"},{"$text":"2","name":"SW","typeId":"a354-c1c8-a745-f9e3"},{"$text":"Strum","name":"Schlüsselwort","typeId":"7f1b-8591-2fcf-d01c"}],"id":"99cf-4b14-147f-8229","name":"Guardian Spear","hidden":false,"typeId":"f77d-b953-8fa4-b762","typeName":"Fernkampfwaffe","from":"entry"}],"id":"y3mgww","name":"Guardian Spear","entryId":"d0ce-f2d3-358f-4530::e823-5718-f1b6-2702","number":4,"type":"upgrade","from":"entry"}],"id":"y24ol66","name":"Custodian Guard (Guardian Spear)","entryId":"d0ce-f2d3-358f-4530::5bbc-172f-4cb8-e6da","entryGroupId":"d0ce-f2d3-358f-4530::a293-9470-77c1-c8da","number":4,"type":"model","from":"group","group":"4-5 Custodian Guard"}],"costs":[{"name":"pkt","typeId":"51b2-306e-1021-d207","value":160}],"categories":[{"id":"c4f-4c5f-3507-e4bc","name":"Custodian Guard","entryId":"c4f-4c5f-3507-e4bc","primary":false},{"id":"cf47-a0d7-7207-29dc","name":"Infanterie","entryId":"cf47-a0d7-7207-29dc","primary":false},{"id":"e338-111e-d0c6-b687","entryId":"e338-111e-d0c6-b687","name":"Linientruppen","primary":true},{"id":"aff3-d6a3-2a95-9dc","name":"Imperium","entryId":"aff3-d6a3-2a95-9dc","primary":false},{"id":"eea5-aeaf-bbf0-d5ee","name":"Fraktion; Adeptus Custodes","entryId":"eea5-aeaf-bbf0-d5ee","primary":false}],"id":"xs9zrnr","name":"Custodian Guard","entryId":"d0ce-f2d3-358f-4530::91b3-2e1c-e642-d213","number":1,"type":"unit","from":"entry"}'::jsonb) on conflict (id) do update set name = excluded.name, model_count = excluded.model_count, profile_name = excluded.profile_name, movement_text = excluded.movement_text, toughness = excluded.toughness, save = ex