insert into public.army_units (id, roster_id, source_file, name, model_count, profile_name, movement_text, toughness, save, wounds_per_model, leadership_text, objective_control, raw_selection) values ('guidos-army-aggro-style::69e906e51b1e13f3b8b12d4a', 'guidos-army-aggro-style', 'Guidos Army - aggro style.json', 'Allarus Custodians', 1, 'Allarus Custodian', '5"', 7, 2, 4, '6+', 2, '{"rules":[{"description":"During the Declare Battle Formations step, if every model in a unit has this ability, you can set it up in Reserves instead of setting it up on the battlefield. If you do, in the Reinforcements step of one of your Movement phases you can set up this unit anywhere on the battlefield that is more than 9\" horizontally away from all enemy models.\n\nIf a unit with the Deep Strike ability arrives from Strategic Reserves, the controlling player can choose for that unit to be set up either using the rules for Strategic Reserves or using the Deep Strike ability.","id":"7cb5-dd6b-dd87-ad3b","name":"Schocktruppen","hidden":false,"page":39},{"description":"Each time a unit with this ability is selected to fight, select one of the Ka''tah stances below. Until that unit has finished making its attacks, the selected Stance is active for it and it gains the relevant ability.\n\n■ DACATARAI STANCE\nMelee weapons equipped by models in this unit have the [SUSTAINED HITS 1] ability.\n■ RENDAX STANCE\nMelee weapons equipped by models in this unit have the [LETHAL HITS] ability.","id":"e348-7090-3aff-ee2c","name":"Martial Ka''tah","hidden":false}],"profiles":[{"characteristics":[{"$text":"Each time a model in this unit makes an attack that targets a ^^Character, Monster^^ or ^^Vehicle^^ unit, you can re-roll the Wound roll.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"d569-61db-406d-1d42","name":"Slayers of Tyrants","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"Once per battle, at the end of your opponent''s turn, if this unit is not within Engagement Range of one or more enemy units, you can remove it from the battlefield and place it into Strategic Reserves.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"0a36-c494-baad-91db","name":"From Golden Light","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"5\"","name":"B","typeId":"e703-ecb6-5ce7-aec1"},{"$text":"7","name":"W","typeId":"d29d-cf75-fc2d-34a4"},{"$text":"2+","name":"RW","typeId":"450-a17e-9d5e-29da"},{"$text":"4","name":"LP","typeId":"750a-a2ec-90d3-21fe"},{"$text":"6+","name":"MW","typeId":"58d2-b879-49c7-43bc"},{"$text":"2","name":"MK","typeId":"bef7-942a-1a23-59f8"}],"id":"fe8b-58b8-b37c-39b6","name":"Allarus Custodian","hidden":false,"typeId":"c547-1836-d8a-ff4f","typeName":"Einheit","from":"entry"},{"characteristics":[{"$text":"Models in this unit have a 4+ invulnerable save.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"0300-84b9-69cf-b64f","name":"Invulnerable Save","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"}],"selections":[{"selections":[{"rules":[{"description":"Weapons with **[BLAST]** in their profile are known as Blast weapons, and they make a random number of attacks. Each time you determine how many attacks are made with a Blast weapon, add 1 to the result for every five models that were in the target unit when you selected it as the target (rounding down). Blast weapons can never be used to make attacks against a unit that is within Engagement Range of one or more units from the attacking model’s army (including its own unit).","id":"6c1f-1cf7-ff25-c99e","name":"Explosiv","hidden":false,"page":26}],"profiles":[{"characteristics":[{"$text":"18\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"D6","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"2+","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"4","name":"S","typeId":"2229-f494-25