insert into public.army_units (id, roster_id, source_file, name, model_count, profile_name, movement_text, toughness, save, wounds_per_model, leadership_text, objective_control, raw_selection) values ('guidos-army-aggro-style::dmxccm', 'guidos-army-aggro-style', 'Guidos Army - aggro style.json', 'Witchseekers', 5, 'Witchseeker Sister Superior', '6"', 3, 3, 1, '6+', 1, '{"rules":[{"description":"Some units have ‘Scouts x\"’ listed in their abilities. If every model in a unit has this ability, then at the start of the first battle round, before the first turn begins, it can make a Normal move of up to x\", with the exception that, while making that move, the distance moved by each model in that unit can be greater than that model''s Move characteristic, as long as it is not greater than x\". \n\nDEDICATED TRANSPORT models can make use of any Scouts x\" ability listed in their abilities, or a Scouts x\" ability that a unit that starts the battle embarked within that DEDICATED TRANSPORT  model has (provided only models with this ability are embarked within that Dedicated Transport model), regardless of how that embarked unit gained this ability (e.g. listed in their abilities, conferred by an Enhancement or by an attached Character, etc.). \n\nA unit that moves using this ability must end that move more than 9\" horizontally away from all enemy models. If both players have units that can do this, the player who is taking the first turn moves their units first.","id":"ada6-bac1-ffe0-d6f7","name":"Kundschafter 6\"","hidden":false,"page":39}],"profiles":[{"characteristics":[{"$text":"In your Shooting phase, after this unit has shot, select one enemy unit that was hit by one or more of those attacks. That unit must take a Battle-shock test.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"6449-d735-2ac6-02b1","name":"Sanctified Flames","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"This model has the Feel No Pain 3+ ability against Psychic Attacks and mortal wounds.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"b95d-04e9-97fd-4125","name":"Daughter of the Abyss","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"}],"selections":[{"profiles":[{"characteristics":[{"$text":"6\"","name":"B","typeId":"e703-ecb6-5ce7-aec1"},{"$text":"3","name":"W","typeId":"d29d-cf75-fc2d-34a4"},{"$text":"3+","name":"RW","typeId":"450-a17e-9d5e-29da"},{"$text":"1","name":"LP","typeId":"750a-a2ec-90d3-21fe"},{"$text":"6+","name":"MW","typeId":"58d2-b879-49c7-43bc"},{"$text":"1","name":"MK","typeId":"bef7-942a-1a23-59f8"}],"id":"f997-71c0-570d-3a3e","name":"Witchseeker Sister Superior","hidden":false,"typeId":"c547-1836-d8a-ff4f","typeName":"Einheit","from":"entry"}],"selections":[{"profiles":[{"characteristics":[{"$text":"Nahkampf","name":"Reichweite","typeId":"914c-b413-91e3-a132"},{"$text":"2","name":"A","typeId":"2337-daa1-6682-b110"},{"$text":"3+","name":"KG","typeId":"95d1-95f-45b4-11d6"},{"$text":"3","name":"S","typeId":"ab33-d393-96ce-ccba"},{"$text":"0","name":"DS","typeId":"41a0-1301-112a-e2f2"},{"$text":"1","name":"SW","typeId":"3254-9fe6-d824-513e"},{"$text":"-","name":"Schlüsselwort","typeId":"893f-9000-ccf7-648e"}],"id":"704a-ab7f-5185-e15f","name":"Close combat weapon","hidden":false,"typeId":"8a40-4aaa-c780-9046","typeName":"Nahkampfwaffen","from":"entry"}],"id":"ea8xv05b","name":"Close combat weapon","entryId":"23ec-128a-efbe-797f::b2c8-11fc-e5ad-6fda","number":1,"type":"upgrade","from":"entry"},{"rules":[{"description":"Weapons with **[IGNORES COVER]** in their profile are known as Ignores Cover weapons. Each time an attack is made with such a weapon, the target cannot have the Benefit of Cover against that attack.","id":"4640-43e7-30b-215a","name":"Deckung Ignorieren","hidden":false,"page":25},{"description":"Weapons with **[TORRENT]** in their profile are known as Torrent weapons. Each time an attack is made with s