typeId":"41a0-1301-112a-e2f2"},{"$text":"1","name":"SW","typeId":"3254-9fe6-d824-513e"},{"$text":"-","name":"Schlüsselwort","typeId":"893f-9000-ccf7-648e"}],"id":"9a82-220f-847b-5799","name":"Close combat weapon","hidden":false,"typeId":"8a40-4aaa-c780-9046","typeName":"Nahkampfwaffen","from":"entry"}],"id":"eqa9ow9","name":"Close combat weapon","entryId":"23ec-128a-efbe-797f::48db-ef5a-eb2f-f44","number":4,"type":"upgrade","from":"entry"},{"rules":[{"description":"Weapons with **[IGNORES COVER]** in their profile are known as Ignores Cover weapons. Each time an attack is made with such a weapon, the target cannot have the Benefit of Cover against that attack.","id":"4640-43e7-30b-215a","name":"Deckung Ignorieren","hidden":false,"page":25},{"description":"Weapons with **[TORRENT]** in their profile are known as Torrent weapons. Each time an attack is made with such a weapon, that attack automatically hits the target.","id":"5edf-d619-23e0-9b56","name":"Schwall","hidden":false,"page":25}],"profiles":[{"characteristics":[{"$text":"12\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"D6","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"N/A","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"4","name":"S","typeId":"2229-f494-25db-c5d3"},{"$text":"0","name":"DS","typeId":"9ead-8a10-520-de15"},{"$text":"1","name":"SW","typeId":"a354-c1c8-a745-f9e3"},{"$text":"Ignoriert Deckung, Schwall","name":"Schlüsselwort","typeId":"7f1b-8591-2fcf-d01c"}],"id":"fa7d-bddc-8b89-3575","name":"Witchseeker flamer","hidden":false,"typeId":"f77d-b953-8fa4-b762","typeName":"Fernkampfwaffe","from":"entry"}],"categories":[{"id":"e993-e086-6de1-12af","name":"Attacks Dx Weapon","entryId":"e993-e086-6de1-12af","primary":false}],"id":"eqnweik","name":"Witchseeker flamer","entryId":"23ec-128a-efbe-797f::ddcf-8c04-1885-1afc::f12b-b113-de8a-4f1e","number":4,"type":"upgrade","from":"entry"}],"id":"eqa7nas","name":"Witchseeker","entryId":"23ec-128a-efbe-797f::9fdd-e31a-5f28-85ea","entryGroupId":"23ec-128a-efbe-797f::fdc6-1797-8971-6964","number":4,"type":"model","from":"group","group":"3-9 Witchseekers"}],"costs":[{"name":"pkt","typeId":"51b2-306e-1021-d207","value":55}],"categories":[{"id":"e4c0-5321-5d49-dfcb","name":"Witchseekers","entryId":"e4c0-5321-5d49-dfcb","primary":false},{"id":"eea5-aeaf-bbf0-d5ee","name":"Fraktion; Adeptus Custodes","entryId":"eea5-aeaf-bbf0-d5ee","primary":false},{"id":"9177-5477-63dd-38d","name":"Anathema Psykana","entryId":"9177-5477-63dd-38d","primary":false},{"id":"cf47-a0d7-7207-29dc","entryId":"cf47-a0d7-7207-29dc","name":"Infanterie","primary":true},{"id":"aff3-d6a3-2a95-9dc","name":"Imperium","entryId":"aff3-d6a3-2a95-9dc","primary":false}],"id":"dmxccm","name":"Witchseekers","entryId":"23ec-128a-efbe-797f::503b-f7be-eeeb-9e31","number":1,"type":"unit","from":"entry"}'::jsonb) on conflict (id) do update set name = excluded.name, model_count = excluded.model_count, profile_name = excluded.profile_name, movement_text = excluded.movement_text, toughness = excluded.toughness, save = excluded.save, wounds_per_model = excluded.wounds_per_model, leadership_text = excluded.leadership_text, objective_control = excluded.objective_control, raw_selection = excluded.raw_selection, updated_at = now();
insert into public.army_units (id, roster_id, source_file, name, model_count, profile_name, movement_text, toughness, save, wounds_per_model, leadership_text, objective_control, raw_selection) values ('wraith-kern-basis::1ugsdeh', 'wraith-kern-basis', 'Wraith Kern - Basis.json', 'Farseer Skyrunner', 1, 'Farseer Skyrunner', '14"', 4, 6, 5, '6+', 2, '{"rules":[{"description":"If your Army Faction is ^^Asuryani^^, at the start of the battle round, you receive a number of Battle Focus tokens based on the battle size, as shown below:\n\n\n■ Incursion - 2\n■ Strike Force - 4\n■ Onslaught - 6\n\n\nEach time one of the triggers shown in the Agile Manoeuvres section of your codex occurs, you can spend one Battle focus token to enable the relevant eligible unit to perform that Agile Manoeuvre. A unit is eligible to perform an Agile Manoeuvre if it has this ability and has not already performed an Agile Manoeuvre in the same phase. Unless otherwise stated, you cannot trigger the same Agile Manoeuvre more than once per phase. At the end of the battle round, all unspent Battle Focus tokens are lost.","id":"c324-e193-e23c-7d2e","name":"Battle Focus","hidden":false},{"description":"While a Bodyguard unit contains a Leader, it is known as an Attached unit and, with the exception of rules that are triggered when units are destroyed (pg 12), it is treated as a single unit for all rules purposes. Each time an attack targets an Attached unit, until the attacking unit has resolved all of its attacks, you must use the Toughness characteristic of the Bodyguard models in that unit, even if a Leader in that unit has a different Toughness characteristic. Each time an attack successfully wounds an Attached unit, that attack cannot be allocated to a Character model in that unit, even if that Character model has lost one or more wounds or has already had attacks allocated to it this phase. As soon as the last Bodyguard model in an Attached unit has been destroyed, any attacks made against that unit that have yet to be allocated can then be allocated to Character models in that unit.\n\nEach time the last model in a Bodyguard unit is destroyed, each CHARACTER unit that is part of that Attached unit becomes a separate unit, with its original Starting Strength. If this happens as the result of an attack, they become separate units after the attacking unit has resolved all of its attacks. \n\nEach time the last model in a CHARACTER unit that is attached to a Bodyguard unit is destroyed and there is not another CHARACTER unit attached, that Attached unit’s Bodyguard unit becomes a separate unit, with its original Starting Strength. If this happens as the result of an attack, they become separate units after the attacking unit has resolved all of its attacks. \n\nEach time a unit that is part of an Attached unit is destroyed, it does not have the keywords of any other units that make up that Attached unit (unless it has those keywords on its own datasheet) for the purposes of any rules that would be triggered when that unit is destroyed.","id":"b4dd-3e1f-41cb-218f","name":"Anführer","hidden":false,"page":39}],"profiles":[{"characteristics":[{"$text":"A Farseer Skyrunner has a 4+ Invulnerable save","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"a5f6-a46f-82c2-cdfb","name":"Invulnerable Save (Farseer)","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"While this model is leading a unit, once per phase you can change the result of one Hit roll, one Wound roll, or one Damage roll made for a model in that unit to an unmodified 6.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"47ca-e9d7-e55f-17f8","name":"Branching Fates (Psychic)","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"At the end of your Movement phase, select one enemy unit within 18\" of and visible to this model. Until the start of your next Command phase, each time a model in that unit makes an attack, subtract 1 from the Wound roll. Each unit can only be selected for this ability once per turn.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"5845-10af-ea52-4dd3","name":"Misfortune (Psychic)","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"This model can be attached to the following units:\n■ Warlock Skyrunners\n■ Windriders","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"60c7-3eec-1396-ae4d","name":"Anführer","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"14\"","name":"B","typeId":"e703-ecb6-5ce7-aec1"},{"$text":"4","name":"W","typeId":"d29d-cf75-fc2d-34a4"},{"$text":"6+","name":"RW","typeId":"450-a17e-9d5e-29da"},{"$text":"5","name":"LP","typeId":"750a-a2ec-90d3-21fe"},{"$text":"6+","name":"MW","typeId":"58d2-b879-49c7-43bc"},{"$text":"2","name":"MK","typeId":"bef7-942a-1a23-59f8"}],"id":"5f18-4793-74a7-b6c2","name":"Farseer Skyrunner","hidden":false,"typeId":"c547-1836-d8a-ff4f","typeName":"Einheit","from":"entry"}],"selections":[{"rules":[{"description":"Weapons with **[BLAST]** in their profile are known as Blast weapons, and they make a random number of attacks. Each time you determine how many attacks are made with a Blast weapon, add 1 to the result for every five models that were in the target unit when you selected it as the target (rounding down). Blast weapons can never be used to make attacks against a unit that is within Engagement Range of one or more units from the attacking model’s army (including its own unit).","id":"6c1f-1cf7-ff25-c99e","name":"Explosiv","hidden":false,"page":26},{"description":"Some weapons and abilities can only be used by **^^Psykers^^**. Such weapons and abilities are tagged with the word ''Psychic''. If a Psychic weapon or ability causes any unit to suffer one or more wounds, each of those wounds is considered to have been inflicted by a Psychic Attack.","id":"e9c4-2bb8-12ee-cd1b","name":"Psychic","hidden":false,"page":38}],"profiles":[{"characteristics":[{"$text":"24\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"D6","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"3+","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"6","name":"S","typeId":"2229-f494-25db-c5d3"},{"$text":"-2","name":"DS","typeId":"9ead-8a10-520-de15"},{"$text":"D3","name":"SW","typeId":"a354-c1c8-a745-f9e3"},{"$text":"Blast, Psychic","name":"Schlüsselwort","typeId":"7f1b-8591-2fcf-d01c"}],"id":"b718-46ea-b550-2352","name":"Eldritch Storm","hidden":false,"typeId":"f77d-b953-8fa4-b762","typeName":"Fernkampfwaffe","from":"entry"}],"categories":[{"id":"4546-4a0c-b3be-e84c","name":"Psionische Waffe","entryId":"4546-4a0c-b3be-e84c","primary":false},{"id":"eeda-8544-a2f3-3fab","name":"Fernkampfwaffe","entryId":"eeda-8544-a2f3-3fab","primary":false},{"id":"e993-e086-6de1-12af","name":"Attacks Dx Weapon","entryId":"e993-e086-6de1-12af","primary":false},{"id":"4986-bf86-beb4-13ac","name":"Damage Dx Weapon","entryId":"4986-bf86-beb4-13ac","primary":false}],"id":"1w889l","name":"Eldritch Storm","entryId":"ecf0-2626-e0a3-aaa::5caa-585-9873-9ae9","entryGroupId":"ecf0-2626-e0a3-aaa::be72-1e0f-e109-6b6d","number":1,"type":"upgrade","from":"group","group":"Ausrüstung"},{"rules":[{"description":"Waffen mit  **[PISTOLE]** im Profil werden als Pistolen bezeichnet. Enthält eine Einheit mindestens ein mit Pistole ausgerüstetes Modell, kommt jene Einheit in der Fernkampfphase ihres kontrollierenden Spielers auch dann infrage, zu schiessen, wenn sie in Nahkampfreichweite um feindliche Einheiten ist. Wenn eine solche Einheit gewählt wird, um zu schiessen, kann sie nur Attacken mit ihren Pistolen abhandeln und kann nur eine einzige der feindlichen Einheiten in Nahkampfreichweite um sich als Ziel wählen. Unter diesen Umständen kann eine Pistole auch dann eine feindliche Einheit als Ziel wählen, wenn andere befreundete Einheiten in Nahkampfreichweite um dieselbe feindliche Einheit sind.\n\nWenn ein Modell mit einer oder mehreren Pistolen ausgerüstet ist und es sich nicht um ein **^^Monster^^** oder **^^Fahrzeug^^**- Modell handelt, kann es entweder mit seinen Pistolen oder mit all seinen anderen Fernkampfwaffen schiessen. Sage an , ob ein solches Modell mit seinen Pistolen oder mit seinen anderen Fernkampfwaffen schiesst, bevor du Ziele wählst.","id":"8bf7-8812-923d-29e4","name":"Pistole","hidden":false,"page":25},{"description":"Weapons with **[ASSAULT]** in their profile are known as Assault weapons. If a unit that Advanced this turn contains any models equipped with Assault weapons, it is still eligible to shoot in this turn’s Shooting phase. When such a unit is selected to shoot, you can only resolve attacks using Assault weapons its models are equipped with.","id":"fc8a-8c24-bae9-cc1c","name":"Strum","hidden":false,"page":25}],"profiles":[{"characteristics":[{"$text":"12\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"1","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"3+","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"4","name":"S","typeId":"2229-f494-25db-c5d3"},{"$text":"-1","name":"DS","typeId":"9ead-8a10-520-de15"},{"$text":"1","name":"SW","typeId":"a354-c1c8-a745-f9e3"},{"$text":"Assault, Pistol","name":"Schlüsselwort","typeId":"7f1b-8591-2fcf-d01c"}],"id":"7825-a114-ca5f-1bc2","name":"Shuriken Pistol","hidden":false,"typeId":"f77d-b953-8fa4-b762","typeName":"Fernkampfwaffe","from":"entry"}],"categories":[{"id":"eeda-8544-a2f3-3fab","name":"Fernkampfwaffe","entryId":"eeda-8544-a2f3-3fab","primary":false}],"id":"1w5icej","name":"Shuriken Pistol","entryId":"ecf0-2626-e0a3-aaa::b022-c256-b6a3-e636","entryGroupId":"ecf0-2626-e0a3-aaa::be72-1e0f-e109-6b6d","number":1,"type":"upgrade","from":"group","group":"Ausrüstung"},{"rules":[{"description":"Weapons with **[ASSAULT]** in their profile are known as Assault weapons. If a unit that Advanced this turn contains any models equipped with Assault weapons, it is still eligible to shoot in this turn’s Shooting phase. When such a unit is selected to shoot, you can only resolve attacks using Assault weapons its models are equipped with.","id":"fc8a-8c24-bae9-cc1c","name":"Strum","hidden":false,"page":25},{"description":"Weapons with **[TWIN-LINKED]** in their profile are known as Twin-linked weapons. Each time an attack is made with such a weapon, you can re-roll that attack’s Wound roll.","id":"cf93-ad4d-2f08-a79d","name":"Synchronisiert","hidden":false,"page":25}],"profiles":[{"characteristics":[{"$text":"18\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"2","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"3+","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"4","name":"S","typeId":"2229-f494-25db-c5d3"},{"$text":"-1","name":"DS","typeId":"9ead-8a10-520-de15"},{"$text":"1","name":"SW","typeId":"a354-c1c8-a745-f9e3"},{"$text":"Assault, Twin Linked","name":"Schlüsselwort","typeId":"7f1b-8591-2fcf-d01c"}],"id":"5fa6-19eb-f75e-a41","name":"Twin Shuriken Catapult","hidden":false,"typeId":"f77d-b953-8fa4-b762","typeName":"Fernkampfwaffe","from":"entry"}],"categories":[{"id":"eeda-8544-a2f3-3fab","name":"Fernkampfwaffe","entryId":"eeda-8544-a2f3-3fab","primary":false}],"id":"1w4q71c","name":"Twin Shuriken Catapult","entryId":"ecf0-2626-e0a3-aaa::511-add5-c4b5-4302","entryGroupId":"ecf0-2626-e0a3-aaa::be72-1e0f-e109-6b6d","number":1,"type":"upgrade","from":"group","group":"Ausrüstung"},{"rules":[{"description":"Some weapons and abilities can only be used by **^^Psykers^^**. Such weapons and abilities are tagged with the word ''Psychic''. If a Psychic weapon or ability causes any unit to suffer one or more wounds, each of those wounds is considered to have been inflicted by a Psychic Attack.","id":"e9c4-2bb8-12ee-cd1b","name":"Psychic","hidden":false,"page":38},{"description":"Weapons with **[ASSAULT]** in their profile are known as Assault weapons. If a unit that Advanced this turn contains any models equipped with Assault weapons, it is still eligible to shoot in this turn’s Shooting phase. When such a unit is selected to shoot, you can only resolve attacks using Assault weapons its models are equipped with.","id":"fc8a-8c24-bae9-cc1c","name":"Strum","hidden":false,"page":25}],"profiles":[{"characteristics":[{"$text":"12\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"1","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"3+","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"9","name":"S","typeId":"2229-f494-25db-c5d3"},{"$text":"0","name":"DS","typeId":"9ead-8a10-520-de15"},{"$text":"3","name":"SW","typeId":"a354-c1c8-a745-f9e3"},{"$text":"Assault, Psychic","name":"Schlüsselwort","typeId":"7f1b-8591-2fcf-d01c"}],"id":"a4b8-2ce3-93a2-f98b","name":"Singing Spear","hidden":false,"typeId":"f77d-b953-8fa4-b762","typeName":"Fernkampfwaffe","from":"entry"},{"characteristics":[{"$text":"Nahkampf","name":"Reichweite","typeId":"914c-b413-91e3-a132"},{"$text":"2","name":"A","typeId":"2337-daa1-6682-b110"},{"$text":"2+","name":"KG","typeId":"95d1-95f-45b4-11d6"},{"$text":"3","name":"S","typeId":"ab33-d393-96ce-ccba"},{"$text":"0","name":"DS","typeId":"41a0-1301-112a-e2f2"},{"$text":"3","name":"SW","typeId":"3254-9fe6-d824-513e"},{"$text":"Psychic","name":"Schlüsselwort","typeId":"893f-9000-ccf7-648e"}],"id":"938f-d1ee-fb90-c89c","name":"Singing Spear","hidden":false,"typeId":"8a40-4aaa-c780-9046","typeName":"Nahkampfwaffen","from":"entry"}],"categories":[{"id":"4546-4a0c-b3be-e84c","name":"Psionische Waffe","entryId":"4546-4a0c-b3be-e84c","primary":false},{"id":"eeda-8544-a2f3-3fab","name":"Fernkampfwaffe","entryId":"eeda-8544-a2f3-3fab","primary":false},{"id":"ccdd-3987-11ed-90cd","name":"Nahkampfwaffe","entryId":"ccdd-3987-11ed-90cd","primary":false}],"id":"tb4q3qd","name":"Singing Spear","entryId":"ecf0-2626-e0a3-aaa::e1b4-2787-f402-c30d","entryGroupId":"ecf0-2626-e0a3-aaa::61d1-bf62-7eee-8830","number":1,"type":"upgrade","from":"group","group":"Ausrüstung::Weapon"}],"costs":[{"name":"pkt","typeId":"51b2-306e-1021-d207","value":80}],"categories":[{"id":"4fdc-b86b-a0d7-8698","name":"Farseer Skyrunner","entryId":"4fdc-b86b-a0d7-8698","primary":false},{"id":"851f-4e16-2f8d-17ae","name":"Farseer","entryId":"851f-4e16-2f8d-17ae","primary":false},{"id":"9cfd-1c32-585f-7d5c","entryId":"9cfd-1c32-585f-7d5c","name":"Charatker","primary":true},{"id":"c619-2086-bbcf-69c9","name":"Fliegen","entryId":"c619-2086-bbcf-69c9","primary":false},{"id":"14a0-40c9-2748-ae6e","name":"Beritten","entryId":"14a0-40c9-2748-ae6e","primary":false},{"id":"13bf-2bee-3ae0-b414","name":"Psioniker","entryId":"13bf-2bee-3ae0-b414","primary":false},{"id":"4378-1827-4988-be4e","name":"Fraktion: Asuryani","entryId":"4378-1827-4988-be4e","primary":false},{"id":"e035-51fc-813a-1313","name":"Aeldari","entryId":"e035-51fc-813a-1313","primary":false},{"id":"9032-f917-9bc5-fd47","name":"Ynnari","entryId":"9032-f917-9bc5-fd47","primary":false}],"id":"1ugsdeh","name":"Farseer Skyrunner","entryId":"ecf0-2626-e0a3-aaa::833b-55bc-73be-8862","number":1,"type":"model","from":"entry"}'::jsonb) on conflict (id) do update set name = excluded.name, model_count = excluded.model_count, profile_name = excluded.profile_name, movement_text = excluded.movement_text, toughness = excluded.toughness, save = excluded.save, wounds_per_model = excluded.wounds_per_model, leadership_text = excluded.leadership_text, objective_control = excluded.objective_control, raw_selection = excluded.raw_selection, updated_at = now();
insert into public.army_units (id, roster_id, source_file, name, model_count, profile_name, movement_text, toughness, save, wounds_per_model, leadership_text, objective_control, raw_selection) values ('wraith-kern-basis::q4lspy', 'wraith-kern-basis', 'Wraith Kern - Basis.json', 'Spiritseer', 1, 'Spiritseer', '7"', 3, 6, 3, '6+', 1, '{"rules":[{"description":"If your Army Faction is ^^Asuryani^^, at the start of the battle round, you receive a number of Battle Focus tokens based on the battle size, as shown below:\n\n\n■ Incursion - 2\n■ Strike Force - 4\n■ Onslaught - 6\n\n\nEach time one of the triggers shown in the Agile Manoeuvres section of your codex occurs, you can spend one Battle focus token to enable the relevant eligible unit to perform that Agile Manoeuvre. A unit is eligible to perform an Agile Manoeuvre if it has this ability and has not already performed an Agile Manoeuvre in the same phase. Unless otherwise stated, you cannot trigger the same Agile Manoeuvre more than once per phase. At the end of the battle round, all unspent Battle Focus tokens are lost.","id":"c324-e193-e23c-7d2e","name":"Battle Focus","hidden":false},{"description":"If every model in a unit has this ability, then each time a ranged attack is made against it, subtract 1 from that attack’s Hit roll.","id":"bec5-4288-34a6-ccfa","name":"Tarnung","hidden":false,"page":20}],"profiles":[{"characteristics":[{"$text":"A Spiritseer has a 4+ Invulnerable save","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"b5db-90c2-7d23-91f9","name":"Invulnerable Save (Spiritseer)","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"7\"","name":"B","typeId":"e703-ecb6-5ce7-aec1"},{"$text":"3","name":"W","typeId":"d29d-cf75-fc2d-34a4"},{"$text":"6+","name":"RW","typeId":"450-a17e-9d5e-29da"},{"$text":"3","name":"LP","typeId":"750a-a2ec-90d3-21fe"},{"$text":"6+","name":"MW","typeId":"58d2-b879-49c7-43bc"},{"$text":"1","name":"MK","typeId":"bef7-942a-1a23-59f8"}],"id":"976c-aa8a-1efc-10b4","name":"Spiritseer","hidden":false,"typeId":"c547-1836-d8a-ff4f","typeName":"Einheit","from":"entry"},{"characteristics":[{"$text":"Once per turn, in your Movement phase, when this model starts or ends a move, select one friendly Wraith Construct unit within 6\" of this model (excluding Titanic units) and one enemy unit visible to this model. Until the start of your next Movement phase, weapons equipped by models in that friendly unit have the [Sustained Hits 1] ability while targeting that enemy unit.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"255b-3bb3-dbc6-f9bb","name":"Spirit Mark (Psychic)","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"In your Command phase, select one friendly Wraith Construct unit within 6\" of this model. If one or more models in that unit are destroyed, you can return one destroyed model to that unit. Otherwise, one model in that unit regains up to D3 lost wounds. Each unit can only be selected for this ability once per turn.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"f781-d34a-675f-28bf","name":"Tears of Isha (Psychic)","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"While this model is within 3\" of one or more friendly Wraith Construct units, this model has the Lone Operative ability.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"10d8-76d2-6689-5b6b","name":"Spiritseer","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"}],"selections":[{"categories":[{"id":"5c0e-4c31-d51b-e470","name":"Kriegsherr","entryId":"5c0e-4c31-d51b-e470","primary":false}],"id":"8kfk0zm","name":"Kriegsherr","entryId":"2a7d-902-33d3-f639::e195-edc0-9a27-6907::3f04-19ab-bfb0-6c67","number":1,"type":"upgrade","from":"entry"},{"rules":[{"description":"Weapons with **[ASSAULT]** in their profile are known as Assault weapons. If a unit that Advanced this turn contains any models equipped with Assault weapons, it is still eligible to shoot in this turn’s Shooting phase. When such a unit is selected to shoot, you can only resolve attacks using Assault weapons its models are equipped with.","id":"fc8a-8c24-bae9-cc1c","name":"Strum","hidden":false,"page":25},{"description":"Waffen mit  **[PISTOLE]** im Profil werden als Pistolen bezeichnet. Enthält eine Einheit mindestens ein mit Pistole ausgerüstetes Modell, kommt jene Einheit in der Fernkampfphase ihres kontrollierenden Spielers auch dann infrage, zu schiessen, wenn sie in Nahkampfreichweite um feindliche Einheiten ist. Wenn eine solche Einheit gewählt wird, um zu schiessen, kann sie nur Attacken mit ihren Pistolen abhandeln und kann nur eine einzige der feindlichen Einheiten in Nahkampfreichweite um sich als Ziel wählen. Unter diesen Umständen kann eine Pistole auch dann eine feindliche Einheit als Ziel wählen, wenn andere befreundete Einheiten in Nahkampfreichweite um dieselbe feindliche Einheit sind.\n\nWenn ein Modell mit einer oder mehreren Pistolen ausgerüstet ist und es sich nicht um ein **^^Monster^^** oder **^^Fahrzeug^^**- Modell handelt, kann es entweder mit seinen Pistolen oder mit all seinen anderen Fernkampfwaffen schiessen. Sage an , ob ein solches Modell mit seinen Pistolen oder mit seinen anderen Fernkampfwaffen schiesst, bevor du Ziele wählst.","id":"8bf7-8812-923d-29e4","name":"Pistole","hidden":false,"page":25}],"profiles":[{"characteristics":[{"$text":"12\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"1","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"2+","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"4","name":"S","typeId":"2229-f494-25db-c5d3"},{"$text":"-1","name":"DS","typeId":"9ead-8a10-520-de15"},{"$text":"1","name":"SW","typeId":"a354-c1c8-a745-f9e3"},{"$text":"Assault, Pistol","name":"Schlüsselwort","typeId":"7f1b-8591-2fcf-d01c"}],"id":"298b-4390-ceea-9523","name":"Shuriken Pistol","hidden":false,"typeId":"f77d-b953-8fa4-b762","typeName":"Fernkampfwaffe","from":"entry"}],"categories":[{"id":"eeda-8544-a2f3-3fab","name":"Fernkampfwaffe","entryId":"eeda-8544-a2f3-3fab","primary":false}],"id":"q6h7m0i","name":"Shuriken Pistol","entryId":"2a7d-902-33d3-f639::4796-e6f6-4070-94c4::f550-9922-c96a-805f","entryGroupId":"2a7d-902-33d3-f639::1171-815a-1a8c-299c","number":1,"type":"upgrade","from":"group","group":"Ausrüstung"},{"rules":[{"description":"Weapons with **[ANTI-KEYWORD X+]** in their profile are known as Anti weapons. Each time an attack is made with such a weapon against a target with the keyword after the word ‘Anti-’, an unmodified Wound roll of ‘x+’ scores a Critical Wound.","id":"4111-82e3-9444-e942","name":"Anti-","hidden":false,"page":28},{"description":"Some weapons and abilities can only be used by **^^Psykers^^**. Such weapons and abilities are tagged with the word ''Psychic''. If a Psychic weapon or ability causes any unit to suffer one or more wounds, each of those wounds is considered to have been inflicted by a Psychic Attack.","id":"e9c4-2bb8-12ee-cd1b","name":"Psychic","hidden":false,"page":38}],"profiles":[{"characteristics":[{"$text":"Nahkampf","name":"Reichweite","typeId":"914c-b413-91e3-a132"},{"$text":"2","name":"A","typeId":"2337-daa1-6682-b110"},{"$text":"2+","name":"KG","typeId":"95d1-95f-45b4-11d6"},{"$text":"3","name":"S","typeId":"ab33-d393-96ce-ccba"},{"$text":"0","name":"DS","typeId":"41a0-1301-112a-e2f2"},{"$text":"D3","name":"SW","typeId":"3254-9fe6-d824-513e"},{"$text":"Anti-infantry 2+, Psychic","name":"Schlüsselwort","typeId":"893f-9000-ccf7-648e"}],"id":"ea0d-c143-4e2d-64b3","name":"Witch Staff","hidden":false,"typeId":"8a40-4aaa-c780-9046","typeName":"Nahkampfwaffen","from":"entry"}],"categories":[{"id":"4546-4a0c-b3be-e84c","name":"Psionische Waffe","entryId":"4546-4a0c-b3be-e84c","primary":false},{"id":"ccdd-3987-11ed-90cd","name":"Nahkampfwaffe","entryId":"ccdd-3987-11ed-90cd","primary":false},{"id":"4986-bf86-beb4-13ac","name":"Damage Dx Weapon","entryId":"4986-bf86-beb4-13ac","primary":false}],"id":"q6gczac","name":"Witch Staff","entryId":"2a7d-902-33d3-f639::f5e3-9ba5-5d5b-cc29","entryGroupId":"2a7d-902-33d3-f639::1171-815a-1a8c-299c","number":1,"type":"upgrade","from":"group","group":"Ausrüstung"}],"costs":[{"name":"pkt","typeId":"51b2-306e-1021-d207","value":65}],"categories":[{"id":"7ffc-5ee2-121a-2659","name":"Spiritseer","entryId":"7ffc-5ee2-121a-2659","primary":false},{"id":"9cfd-1c32-585f-7d5c","entryId":"9cfd-1c32-585f-7d5c","name":"Charatker","primary":true},{"id":"cf47-a0d7-7207-29dc","name":"Infanterie","entryId":"cf47-a0d7-7207-29dc","primary":false},{"id":"13bf-2bee-3ae0-b414","name":"Psioniker","entryId":"13bf-2bee-3ae0-b414","primary":false},{"id":"4378-1827-4988-be4e","name":"Fraktion: Asuryani","entryId":"4378-1827-4988-be4e","primary":false},{"id":"e035-51fc-813a-1313","name":"Aeldari","entryId":"e035-51fc-813a-1313","primary":false},{"id":"9032-f917-9bc5-fd47","name":"Ynnari","entryId":"9032-f917-9bc5-fd47","primary":false}],"id":"q4lspy","name":"Spiritseer","entryId":"2a7d-902-33d3-f639::e53b-7d09-eb7c-c6c7","number":1,"type":"model","from":"entry"}'::jsonb) on conflict (id) do update set name = excluded.name, model_count = excluded.model_count, profile_name = excluded.profile_name, movement_text = excluded.movement_text, toughness = excluded.toughness, save = excluded.save, wounds_per_model = excluded.wounds_per_model, leadership_text = excluded.leadership_text, objective_control = excluded.objective_control, raw_selection = excluded.raw_selection, updated_at = now();
