insert into public.army_units (id, roster_id, source_file, name, model_count, profile_name, movement_text, toughness, save, wounds_per_model, leadership_text, objective_control, raw_selection) values ('wraith-kern-basis::10i0f78', 'wraith-kern-basis', 'Wraith Kern - Basis.json', 'Windriders', 3, 'Windriders', '14"', 4, 4, 2, '7+', 2, '{"rules":[{"description":"If your Army Faction is ^^Asuryani^^, at the start of the battle round, you receive a number of Battle Focus tokens based on the battle size, as shown below:\n\n\n■ Incursion - 2\n■ Strike Force - 4\n■ Onslaught - 6\n\n\nEach time one of the triggers shown in the Agile Manoeuvres section of your codex occurs, you can spend one Battle focus token to enable the relevant eligible unit to perform that Agile Manoeuvre. A unit is eligible to perform an Agile Manoeuvre if it has this ability and has not already performed an Agile Manoeuvre in the same phase. Unless otherwise stated, you cannot trigger the same Agile Manoeuvre more than once per phase. At the end of the battle round, all unspent Battle Focus tokens are lost.","id":"c324-e193-e23c-7d2e","name":"Battle Focus","hidden":false}],"profiles":[{"characteristics":[{"$text":"Each time a model in this unit makes a ranged attack, re-roll a Hit roll of 1. If the target of that attack is the closest eligible target, you can re-roll the Hit roll instead.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"efc3-dbdb-925e-d8ba","name":"Swift Demise","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"This unit has a 6+ Invulnerable save","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"fcf0-0d03-a184-5dcd","name":"Invulnerable Save","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"}],"selections":[{"profiles":[{"characteristics":[{"$text":"14\"","name":"B","typeId":"e703-ecb6-5ce7-aec1"},{"$text":"4","name":"W","typeId":"d29d-cf75-fc2d-34a4"},{"$text":"