insert into public.army_units (id, roster_id, source_file, name, model_count, profile_name, movement_text, toughness, save, wounds_per_model, leadership_text, objective_control, raw_selection) values ('wraith-kern-basis::2nzcval', 'wraith-kern-basis', 'Wraith Kern - Basis.json', 'Wraithlord', 1, 'Wraithlord', '8"', 10, 2, 10, '8+', 3, '{"rules":[{"description":"Some models have ''Deadly Demise x'' listed in their abilities. When such a model is destroyed, roll one D6 before removing it from play (if such a model is a TRANSPORT, roll before any embarked models disembark). On a 6, each unit within 6\" of that model suffers a number of mortal wounds denoted by ''x'' (if this is a random number, roll separately for each unit within 6\").","id":"b68a-5ded-65ac-98c","name":"Gefährliches Ende 1","hidden":false,"page":23}],"profiles":[{"characteristics":[{"$text":"8\"","name":"B","typeId":"e703-ecb6-5ce7-aec1"},{"$text":"10","name":"W","typeId":"d29d-cf75-fc2d-34a4"},{"$text":"2+","name":"RW","typeId":"450-a17e-9d5e-29da"},{"$text":"10","name":"LP","typeId":"750a-a2ec-90d3-21fe"},{"$text":"8+","name":"MW","typeId":"58d2-b879-49c7-43bc"},{"$text":"3","name":"MK","typeId":"bef7-942a-1a23-59f8"}],"id":"88b3-1d3c-7879-71a4","name":"Wraithlord","hidden":false,"typeId":"c547-1836-d8a-ff4f","typeName":"Einheit","from":"entry"},{"characteristics":[{"$text":"At the start of the battle, select one of the following keywords: Infantry, Monster, Mounted, Vehicle. Each time this model makes an attack that targets a unit with the selected keyword, re-roll a Hit roll of 1 and re-roll a Wound roll of 1.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"7019-ca5c-4d7e-7b83","name":"Fated Hero","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"While this model is within 12\" of one or more friendly Aeldari Psyker models, improve the Ballistic Skill and Weapon Skill characteristics of weapons equipped by this model by 