insert into public.army_units (id, roster_id, source_file, name, model_count, profile_name, movement_text, toughness, save, wounds_per_model, leadership_text, objective_control, raw_selection) values ('wraith-kern-basis::pmfz39c', 'wraith-kern-basis', 'Wraith Kern - Basis.json', 'Fire Prism', 1, 'Fire Prism', '14"', 9, 3, 12, '7+', 3, '{"rules":[{"description":"Some models have ''Deadly Demise x'' listed in their abilities. When such a model is destroyed, roll one D6 before removing it from play (if such a model is a TRANSPORT, roll before any embarked models disembark). On a 6, each unit within 6\" of that model suffers a number of mortal wounds denoted by ''x'' (if this is a random number, roll separately for each unit within 6\").","id":"b68a-5ded-65ac-98c","name":"Gefährliches Ende D3","hidden":false,"page":23},{"description":"If your Army Faction is ^^Asuryani^^, at the start of the battle round, you receive a number of Battle Focus tokens based on the battle size, as shown below:\n\n\n■ Incursion - 2\n■ Strike Force - 4\n■ Onslaught - 6\n\n\nEach time one of the triggers shown in the Agile Manoeuvres section of your codex occurs, you can spend one Battle focus token to enable the relevant eligible unit to perform that Agile Manoeuvre. A unit is eligible to perform an Agile Manoeuvre if it has this ability and has not already performed an Agile Manoeuvre in the same phase. Unless otherwise stated, you cannot trigger the same Agile Manoeuvre more than once per phase. At the end of the battle round, all unspent Battle Focus tokens are lost.","id":"c324-e193-e23c-7d2e","name":"Battle Focus","hidden":false}],"profiles":[{"characteristics":[{"$text":"14\"","name":"B","typeId":"e703-ecb6-5ce7-aec1"},{"$text":"9","name":"W","typeId":"d29d-cf75-fc2d-34a4"},{"$text":"3+","name":"RW","typeId":"450-a17e-9d5e-29da"},{"$text":"12","name":"LP","typeId":"750a-a2ec-90d3-21fe"},{"$text":"7+","name":"MW","typeId":"58d2-b879-49c7-43bc"},{"$text":"3","name":"MK","typeId":"bef7-942a-1a23-59f8"}],"id":"8b96-e5ef-3632-6f56","name":"Fire Prism","hidden":false,"typeId":"c547-1836-d8a-ff4f","typeName":"Einheit","from":"entry"},{"characteristics":[{"$text":"While this model has 1-4 wounds remaining, each time this model makes an attack, subtract 1 from the Hit roll.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"e0e4-d593-3230-8d98","name":"Damaged: 1-4 Wounds Remaining","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"},{"characteristics":[{"$text":"Each time this model is selected to shoot, you can re-roll one Hit roll and you can re-roll one Wound roll when resolving those attacks.","name":"Beschreibung","typeId":"9b8f-694b-e5e-b573"}],"id":"2cf-e1fe-fd6e-6857","name":"Crystal Matrix","hidden":false,"typeId":"9cc3-6d83-4dd3-9b64","typeName":"Fähigkeit","from":"entry"}],"selections":[{"rules":[{"description":"When selecting targets for this weapon, you can measure range and determine visibility from another friendly FIRE PRISM model that is visible to the bearer. When doing so, this weapon has an Attacks characteristic of 1.","id":"158c-6d6d-dc68-3225","name":"Linked Fire","hidden":false},{"description":"Weapons with **[BLAST]** in their profile are known as Blast weapons, and they make a random number of attacks. Each time you determine how many attacks are made with a Blast weapon, add 1 to the result for every five models that were in the target unit when you selected it as the target (rounding down). Blast weapons can never be used to make attacks against a unit that is within Engagement Range of one or more units from the attacking model’s army (including its own unit).","id":"6c1f-1cf7-ff25-c99e","name":"Explosiv","hidden":false,"page":26}],"profiles":[{"characteristics":[{"$text":"60\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"2D6","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"3+","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"6","name":"S","typeId":"2229-f494-25db-c5d3"},{"$text":"-2","name":"DS","typeId":"9ead-8a10-520-de15"},{"$text":"2","name":"SW","typeId":"a354-c1c8-a745-f9e3"},{"$text":"Explosiv","name":"Schlüsselwort","typeId":"7f1b-8591-2fcf-d01c"}],"id":"cf51-83c3-5e6b-9440","name":"➤ Prism Cannon - dispersed pulse","hidden":false,"typeId":"f77d-b953-8fa4-b762","typeName":"Fernkampfwaffe","from":"entry"},{"characteristics":[{"$text":"60\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"2","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"3+","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"18","name":"S","typeId":"2229-f494-25db-c5d3"},{"$text":"-4","name":"DS","typeId":"9ead-8a10-520-de15"},{"$text":"6","name":"SW","typeId":"a354-c1c8-a745-f9e3"},{"$text":"Linked Fire","name":"Schlüsselwort","typeId":"7f1b-8591-2fcf-d01c"}],"id":"9ca0-fcce-98eb-7efc","name":"➤ Prism Cannon - focused lances","hidden":false,"typeId":"f77d-b953-8fa4-b762","typeName":"Fernkampfwaffe","from":"entry"}],"id":"pndci4c","name":"Prism Cannon","entryId":"90de-b0ab-de85-e40b::4704-9a49-8dee-2852","entryGroupId":"90de-b0ab-de85-e40b::056e-54bd-cfcc-c192","number":1,"type":"upgrade","from":"group","group":"Ausrüstung"},{"profiles":[{"characteristics":[{"$text":"Nahkampf","name":"Reichweite","typeId":"914c-b413-91e3-a132"},{"$text":"3","name":"A","typeId":"2337-daa1-6682-b110"},{"$text":"4+","name":"KG","typeId":"95d1-95f-45b4-11d6"},{"$text":"6","name":"S","typeId":"ab33-d393-96ce-ccba"},{"$text":"0","name":"DS","typeId":"41a0-1301-112a-e2f2"},{"$text":"1","name":"SW","typeId":"3254-9fe6-d824-513e"},{"$text":"-","name":"Schlüsselwort","typeId":"893f-9000-ccf7-648e"}],"id":"af8b-71f6-6396-224","name":"Wraithbone Hull","hidden":false,"typeId":"8a40-4aaa-c780-9046","typeName":"Nahkampfwaffen","from":"entry"}],"id":"pnozic","name":"Wraithbone hull","entryId":"90de-b0ab-de85-e40b::93aa-b39f-e09b-4bd0","entryGroupId":"90de-b0ab-de85-e40b::056e-54bd-cfcc-c192","number":1,"type":"upgrade","from":"group","group":"Ausrüstung"},{"rules":[{"description":"Weapons with **[ASSAULT]** in their profile are known as Assault weapons. If a unit that Advanced this turn contains any models equipped with Assault weapons, it is still eligible to shoot in this turn’s Shooting phase. When such a unit is selected to shoot, you can only resolve attacks using Assault weapons its models are equipped with.","id":"fc8a-8c24-bae9-cc1c","name":"Strum","hidden":false,"page":25},{"description":"Weapons with **[TWIN-LINKED]** in their profile are known as Twin-linked weapons. Each time an attack is made with such a weapon, you can re-roll that attack’s Wound roll.","id":"cf93-ad4d-2f08-a79d","name":"Synchronisiert","hidden":false,"page":25}],"profiles":[{"characteristics":[{"$text":"18\"","name":"Reichweite","typeId":"9896-9419-16a1-92fc"},{"$text":"2","name":"A","typeId":"3bb-c35f-f54-fb08"},{"$text":"3+","name":"BF","typeId":"94d-8a98-cf90-183e"},{"$text":"4","name":"S","typeId":"2229-f494-25db-c5d3"},{"$text":"-1","name":"DS","typeId":"9ead-8a10-520-de15"},{"$text":"1","name":"SW","typeId":"a354-c1c8-a745-f9e3"},{"$text":"Assault, Twin Linked","name":"Schlüsselwort","typeId":"7f1b-8591-2fcf-d01c"}],"id":"638d-416f-93be-165d","name":"Twin Shuriken Catapult","hidden":false,"typeId":"f77d-b953-8fa4-b762","typeName":"Fernkampfwaffe","from":"entry"}],"id":"pnn3okk","name":"Twin Shuriken Catapult","entryId":"90de-b0ab-de85-e40b::68be-f35c-9028-6ca6","entryGroupId":"90de-b0ab-de85-e40b::ac7e-3a52-7e47-2387","number":1,"type":"upgrade","from":"group","group":"Ausrüstung::Hull weapon"}],"costs":[{"name":"pkt","typeId":"51b2-306e-1021-d207","value":150}],"categories":[{"id":"3cdb-f4de-9972-f992","name":"Fire Prism","entryId":"3cdb-f4de-9972-f992","primary":false},{"id":"c619-2086-bbcf-69c9","name":"Fliegen","entryId":"c619-2086-bbcf-69c9","primary":false},{"id":"dbd4-63-af05-998","entryId":"dbd4-63-af05-998","name":"Fahrzeug","primary":true},{"id":"4378-1827-4988-be4e","name":"Fraktion: Asuryani","entryId":"4378-1827-4988-be4